files.scripts/built-smoke.mjs:
import { mkdtemp, readFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { Context } from '@deepseek-ai/cordis'
import * as plugin from '../lib/index.js'

const directory = await mkdtemp(join(tmpdir(), 'qiushi-built-'))
const outputPath = join(directory, 'receipts.jsonl')
const ctx = new Context()
const fiber = await ctx.plugin(plugin, { outputPath })
const session = { id: 'built-session-plaintext' }
ctx.emit('session/event', session, {
  type: 'turn/start',
  seq: 0,
  time: 100,
  data: { turn: 1, text: 'built-message-plaintext' },
})
ctx.emit('tools/result', {
