import { readFile, rm } from 'node:fs/promises'
import { resolve } from 'node:path'

const reportPath = resolve('.npm-dry-run.json')
const expectedFiles = [
  'LICENSE',
  'README.md',
  'README.zh-CN.md',
  'cordis.patch.yml',
  'docs/dsh.plugin.schema.json',
  'dsh.plugin.json',
  'lib/index.js',
  'lib/types/index.d.ts',
  'lib/types/receipt.d.ts',
  'package.json',
].sort()

try {
  const raw = await readFile(reportPath, 'utf8')
  const trimmed = raw.trim()
  const arrayStart = trimmed.lastIndexOf('\n[')
  const objectStart = trimmed.lastIndexOf('\n{')
  const jsonStart = trimmed.startsWith('[') || trimmed.startsWith('{')
    ? -1
    : Math.max(arrayStart, objectStart)
  const jsonText = jsonStart < 0 ? trimmed : trimmed.slice(jsonStart + 1)
  if (!jsonText.startsWith('[') && !jsonText.startsWith('{')) {
    throw new Error('npm dry-run produced no JSON report')
  }
  const parsed = JSON.parse(jsonText)
  const report = Array.isArray(parsed) ? parsed[0] : parsed
  if (report === undefined || !Array.isArray(report.files)) {
    throw new Error('npm lifecycle report contains no package file list')
  }
  const actualFiles = report.files.map(({ path }) => path).sort()
  if (JSON.stringify(actualFiles) !== JSON.stringify(expectedFiles)) {
    throw new Error(`unexpected npm publish file list:\n${actualFiles.join('\n')}`)
  }
  if (report.name !== 'qiushi-dsh-evidence-audit' || report.version !== '0.1.0') {
    throw new Error(`unexpected npm identity: ${report.name}@${report.version}`)
  }
  console.log(`npm publish dry-run passed: ${report.id}; ${actualFiles.length} files`)
} finally {
  await rm(reportPath, { force: true })
}

