import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const pnpmCli = process.env.npm_execpath
if (pnpmCli === undefined) throw new Error('run this smoke through pnpm')

function pnpm(args, cwd) {
  return execFileSync(process.execPath, [pnpmCli, ...args], {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  })
}

const expectedFiles = [
  'package/cordis.patch.yml',
  'package/docs/dsh.plugin.schema.json',
  'package/dsh.plugin.json',
  'package/lib/index.js',
  'package/lib/types/index.d.ts',
  'package/lib/types/receipt.d.ts',
  'package/LICENSE',
  'package/package.json',
  'package/README.md',
  'package/README.zh-CN.md',
].sort()

const temporary = await mkdtemp(join(tmpdir(), 'qiushi-tarball-smoke-'))
try {
  const packDirectory = join(temporary, 'pack')
  const consumer = join(temporary, 'consumer')
  await mkdir(packDirectory)
  await mkdir(consumer)
  const packOutput = pnpm(['pack', '--pack-destination', packDirectory], root).trim()
  const tarball = resolve(root, packOutput.split(/\r?\n/).at(-1) ?? '')
  const packedFiles = execFileSync('tar', ['-tf', tarball], { encoding: 'utf8' })
    .trimEnd()
    .split(/\r?\n/)
    .sort()
  if (JSON.stringify(packedFiles) !== JSON.stringify(expectedFiles)) {
    throw new Error(`unexpected pack list:\n${packedFiles.join('\n')}`)
  }

  await writeFile(join(consumer, 'package.json'), JSON.stringify({
    name: 'qiushi-tarball-consumer',
    private: true,
    type: 'module',
  }), 'utf8')
  pnpm(['add', tarball, '@deepseek-ai/cordis@4.0.1', '--ignore-scripts'], consumer)

  const outputPath = join(consumer, 'receipts.jsonl')
  const smoke = `
    import { Context } from '@deepseek-ai/cordis'
    import * as plugin from 'qiushi-dsh-evidence-audit'
    const ctx = new Context()
    const fiber = await ctx.plugin(plugin, { outputPath: process.env.QIUSHI_SMOKE_OUTPUT })
    ctx.emit('session/event', { id: 'tarball-session' }, {
