  execFileSync(process.execPath, ['--input-type=module', '--eval', smoke], {
    cwd: consumer,
    env: { ...process.env, QIUSHI_SMOKE_OUTPUT: outputPath },
    stdio: 'inherit',
  })
  console.log(`tarball smoke passed: ${basename(tarball)}; ${packedFiles.length} files`)
} finally {
  await rm(temporary, { recursive: true, force: true })
}

