/**
 * Observe-only DeepSeek Harness evidence receipt plugin.
 *
 * @module qiushi-dsh-evidence-audit
 */

import { chmodSync, mkdirSync } from 'node:fs'
import { homedir } from 'node:os'
import { dirname, isAbsolute, join, resolve } from 'node:path'
import type { Context } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
import {
  EvidenceReceiptWriter,
  hashObservedValue,
} from './receipt.ts'
import type { ReceiptInput, Sha256 } from './receipt.ts'

/** Cordis plugin name used by Loader diagnostics. */
export const name = 'qiushi-evidence-audit'

/** Receipt output configuration. */
export interface Config {
  /** Absolute JSONL destination. Omit for `$DSH_HOME/evidence-audit/evidence-receipts.jsonl`. */
  outputPath?: string
}

/** Loader validation for {@link Config}. */
export const Config: z<Config> = (z.object({
  outputPath: z.string(),
}) as z<Config>).default({})

interface SessionLike {
  readonly id: string
}

interface SessionEventLike {
  readonly type: string
  readonly seq: number
  readonly time: number
  readonly data: unknown
  readonly ignorable?: true
}

interface ToolExecutionLike {
  readonly name: string
  readonly callId: string
  readonly rootCallId: string
  readonly arguments: unknown
  readonly parent?: symbol
  readonly agent?: { readonly session: SessionLike }
}

interface ToolResultLike {
  readonly isError: boolean
  readonly content: readonly unknown[]
  readonly value?: unknown
  readonly error?: { readonly info?: { readonly code?: string } }
  readonly meta?: unknown
  readonly additionalContexts?: readonly unknown[]
  readonly concludesTurn?: true
}

interface EvidenceContext {
  readonly logger: { warn(message: string): void }
  on(name: 'session/event', listener: (session: SessionLike, event: SessionEventLike) => void): () => void
  on(name: 'tools/result', listener: (exec: ToolExecutionLike, result: ToolResultLike) => void): () => void
  effect(execute: () => () => Promise<void>, label?: string): unknown
}

/** Resolve the configured path without ever defaulting to the working directory. */
export function resolveOutputPath(
  configuredPath: string | undefined,
  dshHome: string | undefined = process.env.DSH_HOME,
  _cwd: string = process.cwd(),
): string {
  if (configuredPath !== undefined) {
    if (!isAbsolute(configuredPath)) {
      throw new TypeError(`qiushi-evidence-audit: outputPath must be absolute, got ${JSON.stringify(configuredPath)}`)
    }
    return resolve(configuredPath)
  }
  const selectedHome = dshHome === undefined || dshHome.trim().length === 0
    ? join(homedir(), '.dsh')
    : expandHomePath(dshHome)
  const home = resolve(selectedHome)
  return join(home, 'evidence-audit', 'evidence-receipts.jsonl')
}

function expandHomePath(path: string): string {
  if (path === '~') return homedir()
  if (path.startsWith('~/') || path.startsWith('~\\')) return join(homedir(), path.slice(2))
  return path
}

function sessionReceipt(session: SessionLike, event: SessionEventLike): ReceiptInput {
  return {
    kind: 'session-event',
    sessionIdHash: hashObservedValue(session.id),
    eventType: event.type,
    eventSeq: event.seq,
    eventTime: event.time,
    eventDataHash: hashObservedValue(event.data),
    ...event.ignorable === true ? { ignorable: true } : {},
  }
}

function toolReceipt(exec: ToolExecutionLike, result: ToolResultLike): ReceiptInput {
  const sessionIdHash: Sha256 | null = exec.agent === undefined
    ? null
    : hashObservedValue(exec.agent.session.id)
  const outcome = {
    isError: result.isError,
    content: result.content,
    ...result.value === undefined ? {} : { value: result.value },
    ...result.error === undefined ? {} : { error: result.error },
    ...result.meta === undefined ? {} : { meta: result.meta },
    ...result.additionalContexts === undefined ? {} : { additionalContexts: result.additionalContexts },
    ...result.concludesTurn === undefined ? {} : { concludesTurn: result.concludesTurn },
  }
  const errorCode = result.error?.info?.code
  return {
    kind: 'tool-result',
    sessionIdHash,
    toolName: exec.name,
    callIdHash: hashObservedValue(exec.callId),
    rootCallIdHash: hashObservedValue(exec.rootCallId),
    argumentsHash: hashObservedValue(exec.arguments),
    outcomeHash: hashObservedValue(outcome),
    isError: result.isError,
    hasParent: exec.parent !== undefined,
    ...errorCode === undefined ? {} : { errorCode },
  }
}

function appendContained(
  ctx: EvidenceContext,
  writer: EvidenceReceiptWriter,
  source: 'session/event' | 'tools/result',
  create: () => ReceiptInput,
): void {
  try {
    writer.append(create())
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error)
    ctx.logger.warn(`qiushi-evidence-audit: ${source} receipt failed: ${message}`)
  }
}

/**
 * Open the hash chain and register contained observers for both official feeds.
 *
 * @param context - Cordis plugin context.
 * @param config - absolute output override, or the safe Harness-home default.
 */
export async function apply(context: Context, config: Config = {}): Promise<void> {
  const ctx = context as unknown as EvidenceContext
  const path = resolveOutputPath(config.outputPath)
  if (config.outputPath === undefined) {
    mkdirSync(dirname(path), { recursive: true, mode: 0o700 })
    chmodSync(dirname(path), 0o700)
  }
  const writer = await EvidenceReceiptWriter.open(path)
  let disposeSessionEvent: (() => void) | undefined
  let disposeToolResult: (() => void) | undefined
  try {
    disposeSessionEvent = ctx.on('session/event', (session, event) => {
      appendContained(ctx, writer, 'session/event', () => sessionReceipt(session, event))
    })
    disposeToolResult = ctx.on('tools/result', (exec, result) => {
      appendContained(ctx, writer, 'tools/result', () => toolReceipt(exec, result))
    })
    ctx.effect(() => async () => {
      disposeToolResult?.()
      disposeSessionEvent?.()
      await writer.close()
    }, 'qiushi evidence receipt observers and writer')
  } catch (error: unknown) {
    disposeToolResult?.()
    disposeSessionEvent?.()
    await writer.close()
    throw error
  }
}

export {
  EvidenceReceiptWriter,
  canonicalJson,
  hashObservedValue,
  verifyReceiptFile,
} from './receipt.ts'
export type {
  EvidenceReceipt,
  ReceiptInput,
  ReceiptVerification,
  SessionEventReceiptInput,
  Sha256,
  ToolResultReceiptInput,
} from './receipt.ts'

