/**
 * Deterministic JSON hashing and append-only evidence receipt persistence.
 *
 * @module qiushi-dsh-evidence-audit/receipt
 */

import {
  chmodSync,
  closeSync,
  existsSync,
  mkdirSync,
  openSync,
  readFileSync,
  writeSync,
} from 'node:fs'
import { createHash } from 'node:crypto'
import { dirname } from 'node:path'
import { types as utilTypes } from 'node:util'

const HASH_PATTERN = /^sha256:[0-9a-f]{64}$/

/** SHA-256 digest encoded with an explicit algorithm prefix. */
export type Sha256 = `sha256:${string}`

/** Stable fields emitted for one observed durable session event. */
export interface SessionEventReceiptInput {
  kind: 'session-event'
  sessionIdHash: Sha256
  eventType: string
  eventSeq: number
  eventTime: number
  eventDataHash: Sha256
  ignorable?: true
}

/** Stable fields emitted for one authoritative tool outcome. */
export interface ToolResultReceiptInput {
  kind: 'tool-result'
  sessionIdHash: Sha256 | null
  toolName: string
  callIdHash: Sha256
  rootCallIdHash: Sha256
  argumentsHash: Sha256
  outcomeHash: Sha256
  isError: boolean
  hasParent: boolean
  errorCode?: string
}

/** One observation accepted by the receipt writer. */
export type ReceiptInput = SessionEventReceiptInput | ToolResultReceiptInput

/** Common chain fields present on every receipt. */
export interface ReceiptBase {
  schemaVersion: 1
  sequence: number
  collectedAt: number
  previousRecordHash: Sha256 | null
  recordHash: Sha256
}

/** One complete hash-chained evidence receipt. */
export type EvidenceReceipt = ReceiptBase & ReceiptInput

/** Result of checking every line and link in a receipt file. */
export interface ReceiptVerification {
  records: number
  lastRecordHash: Sha256 | null
}

type JsonValue = null | boolean | number | string | JsonValue[] | { [key: string]: JsonValue }

/** Render lossless JSON with recursively sorted object keys. */
export function canonicalJson(value: unknown): string {
  return renderCanonical(value, '$', new Set<object>())
}

function renderCanonical(value: unknown, path: string, ancestors: Set<object>): string {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return JSON.stringify(value)
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError(`${path} is not a finite JSON number`)
    return JSON.stringify(value)
  }
  if (Array.isArray(value)) {
    if (utilTypes.isProxy(value) || Object.getPrototypeOf(value) !== Array.prototype) {
      throw new TypeError(`${path} is not a plain JSON array`)
    }
    if (ancestors.has(value)) throw new TypeError(`${path} contains a circular reference`)
    const ownKeys = Reflect.ownKeys(value)
    for (const key of ownKeys) {
      if (typeof key === 'symbol') throw new TypeError(`${path} contains a non-JSON symbol key`)
      if (key === 'length') continue
      const index = Number(key)
      if (!Number.isSafeInteger(index) || index < 0 || String(index) !== key || index >= value.length) {
        throw new TypeError(`${path} contains non-JSON array property ${JSON.stringify(key)}`)
      }
    }
    ancestors.add(value)
    try {
      const items: string[] = []
      for (let index = 0; index < value.length; index += 1) {
        const descriptor = Object.getOwnPropertyDescriptor(value, index)
        if (descriptor === undefined) throw new TypeError(`${path}[${index}] contains a non-JSON array hole`)
        if (!('value' in descriptor)) throw new TypeError(`${path}[${index}] contains a non-JSON accessor`)
        items.push(renderCanonical(descriptor.value, `${path}[${index}]`, ancestors))
      }
      return `[${items.join(',')}]`
    } finally {
      ancestors.delete(value)
    }
  }
  if (typeof value === 'object') {
    const object = value as Record<string, unknown>
    if (utilTypes.isProxy(object)) throw new TypeError(`${path} is not a plain JSON object`)
    const prototype = Object.getPrototypeOf(object) as object | null
    if (prototype !== Object.prototype && prototype !== null) {
      throw new TypeError(`${path} is not a plain JSON object`)
    }
    if (ancestors.has(object)) throw new TypeError(`${path} contains a circular reference`)
    ancestors.add(object)
    try {
      const keys = Reflect.ownKeys(object)
      if (keys.some(key => typeof key === 'symbol')) throw new TypeError(`${path} contains a non-JSON symbol key`)
      const entries = (keys as string[]).sort().map((key) => {
        const descriptor = Object.getOwnPropertyDescriptor(object, key)
        if (descriptor === undefined) throw new TypeError(`${path}.${key} disappeared during canonicalization`)
        if (!descriptor.enumerable) throw new TypeError(`${path}.${key} is a non-JSON non-enumerable property`)
        if (!('value' in descriptor)) throw new TypeError(`${path}.${key} contains a non-JSON accessor`)
        return `${JSON.stringify(key)}:${renderCanonical(descriptor.value, `${path}.${key}`, ancestors)}`
      })
      return `{${entries.join(',')}}`
    } finally {
      ancestors.delete(object)
    }
  }
  throw new TypeError(`${path} contains non-JSON ${typeof value}`)
}

/** Hash a lossless JSON value without retaining its plaintext representation. */
export function hashObservedValue(value: unknown): Sha256 {
  return sha256(canonicalJson(value))
}

function sha256(text: string): Sha256 {
  return `sha256:${createHash('sha256').update(text, 'utf8').digest('hex')}`
}

function withoutRecordHash(record: Record<string, unknown>): Record<string, unknown> {
  const { recordHash: _recordHash, ...unsigned } = record
  return unsigned
}

function parseReceiptLine(line: string, index: number): Record<string, unknown> {
  let value: unknown
  try {
    value = JSON.parse(line) as JsonValue
  } catch (error: unknown) {
    throw new Error(`line ${index + 1} is not JSON`, { cause: error })
  }
  if (value === null || Array.isArray(value) || typeof value !== 'object') {
    throw new Error(`line ${index + 1} is not a JSON object`)
  }
  return value as Record<string, unknown>
}

function verifyReceiptText(text: string): ReceiptVerification {
  if (text.length === 0) return { records: 0, lastRecordHash: null }
  if (!text.endsWith('\n')) throw new Error('file does not end at a complete JSONL record')
  const lines = text.slice(0, -1).split('\n')
  let previous: Sha256 | null = null
  for (const [index, line] of lines.entries()) {
    if (line.length === 0) throw new Error(`line ${index + 1} is empty`)
    const record = parseReceiptLine(line, index)
    if (record.schemaVersion !== 1) throw new Error(`line ${index + 1} has an unsupported schemaVersion`)
    if (record.sequence !== index) throw new Error(`line ${index + 1} has a non-contiguous sequence`)
    if (record.previousRecordHash !== previous) throw new Error(`line ${index + 1} has the wrong previousRecordHash`)
    if (typeof record.recordHash !== 'string' || !HASH_PATTERN.test(record.recordHash)) {
      throw new Error(`line ${index + 1} has an invalid recordHash`)
    }
    const expected = sha256(canonicalJson(withoutRecordHash(record)))
    if (record.recordHash !== expected) throw new Error(`line ${index + 1} recordHash does not match its fields`)
    previous = record.recordHash as Sha256
  }
  return { records: lines.length, lastRecordHash: previous }
}

/** Verify an existing receipt file from its first record through its last. */
export async function verifyReceiptFile(path: string): Promise<ReceiptVerification> {
  try {
    return verifyReceiptText(readFileSync(path, 'utf8'))
  } catch (error: unknown) {
    throw new Error(`invalid receipt chain at ${JSON.stringify(path)}: ${errorMessage(error)}`, { cause: error })
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

/** Append complete receipt lines through one operating-system append handle. */
export class EvidenceReceiptWriter {
  private closed = false

  private constructor(
    private readonly descriptor: number,
    private readonly clock: () => number,
    private nextSequence: number,
    private previousRecordHash: Sha256 | null,
  ) {}

  /** Open or create a receipt file after validating its complete existing chain. */
  static async open(path: string, clock: () => number = Date.now): Promise<EvidenceReceiptWriter> {
    mkdirSync(dirname(path), { recursive: true, mode: 0o700 })
    const verification = existsSync(path)
      ? await verifyReceiptFile(path)
      : { records: 0, lastRecordHash: null }
    const descriptor = openSync(path, 'a', 0o600)
    try {
      chmodSync(path, 0o600)
    } catch (error: unknown) {
      closeSync(descriptor)
      throw error
    }
    return new EvidenceReceiptWriter(
      descriptor,
      clock,
      verification.records,
      verification.lastRecordHash,
    )
  }

  /** Append one canonical line and advance the in-memory chain head. */
  append(input: ReceiptInput): EvidenceReceipt {
    if (this.closed) throw new Error('evidence receipt writer is closed')
    const unsigned = {
      schemaVersion: 1 as const,
      sequence: this.nextSequence,
      collectedAt: this.clock(),
      previousRecordHash: this.previousRecordHash,
      ...input,
    }
    const record: EvidenceReceipt = {
      ...unsigned,
      recordHash: sha256(canonicalJson(unsigned)),
    }
    writeSync(this.descriptor, `${canonicalJson(record)}\n`, undefined, 'utf8')
    this.nextSequence += 1
    this.previousRecordHash = record.recordHash
    return record
  }

  /** Close the append handle. Repeated calls are harmless. */
  async close(): Promise<void> {
    if (this.closed) return
    this.closed = true
    closeSync(this.descriptor)
  }
}

