import { fork, type ChildProcess } from 'node:child_process'
import { mkdtemp } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { verifyReceiptFile } from '../src/receipt.ts'

function waitForMessage(child: ChildProcess, expected: string): Promise<void> {
  return new Promise((resolvePromise, reject) => {
    const onError = (error: Error) => {
      child.off('message', onMessage)
      reject(error)
    }
    const onMessage = (message: unknown) => {
      if (message !== expected) return
      child.off('error', onError)
      child.off('message', onMessage)
      resolvePromise()
    }
    child.once('error', onError)
    child.on('message', onMessage)
  })
}

function waitForExit(child: ChildProcess): Promise<void> {
  return new Promise((resolvePromise, reject) => {
    child.once('error', reject)
    child.once('exit', (code, signal) => {
      if (code === 0) resolvePromise()
      else reject(new Error(`child exited with code ${String(code)} signal ${String(signal)}`))
    })
  })
}

describe('cross-process boundary', () => {
  it('detects a completed two-process append race on subsequent verification', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-concurrency-'))
    const path = join(directory, 'receipts.jsonl')
    const fixture = resolve('tests/fixtures/concurrent-writer.mjs')
    const children = [0, 1].map(() => fork(fixture, [path], {
      stdio: ['ignore', 'ignore', 'inherit', 'ipc'],
    }))

    await Promise.all(children.map(child => waitForMessage(child, 'ready')))
    const done = children.map(child => waitForMessage(child, 'done'))
    const exited = children.map(waitForExit)
    for (const child of children) child.send('append')
    await Promise.all(done)
    await Promise.all(exited)

    await expect(verifyReceiptFile(path)).rejects.toThrow(/invalid receipt chain/)
  }, 15_000)
})

