import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { mkdtemp } from 'node:fs/promises'
import { Context } from '@deepseek-ai/cordis'
import { describe, expect, it } from 'vitest'
import * as plugin from '../src/index.ts'
import { verifyReceiptFile } from '../src/receipt.ts'

describe('real Cordis runtime smoke', () => {
  it('mounts, observes both event names, and disposes its writer', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-cordis-'))
    const path = join(directory, 'receipts.jsonl')
    const ctx = new Context()
    const fiber = await ctx.plugin(plugin, { outputPath: path })
    const session = { id: 'session-smoke' }

    const emit = ctx.emit.bind(ctx) as (...args: unknown[]) => void
    emit('session/event', session, {
      type: 'turn/start',
      seq: 0,
      time: 100,
      data: { turn: 1 },
    })
    emit('tools/result', {
      name: 'smoke-tool',
      callId: 'call-smoke',
      rootCallId: 'call-smoke',
      arguments: { secret: 'argument-smoke' },
      agent: { session },
    }, {
      isError: false,
      value: { secret: 'result-smoke' },
      content: [{ type: 'text', text: 'result-smoke' }],
    })
    await fiber.dispose()

    expect(await verifyReceiptFile(path)).toMatchObject({ records: 2 })
    const sizeAfterDispose = (await readFile(path)).byteLength
    emit('session/event', session, {
      type: 'turn/after-dispose',
      seq: 1,
      time: 101,
      data: { shouldNotBeObserved: true },
    })
    expect((await readFile(path)).byteLength).toBe(sizeAfterDispose)
    const text = await readFile(path, 'utf8')
    for (const secret of ['session-smoke', 'call-smoke', 'argument-smoke', 'result-smoke']) {
      expect(text).not.toContain(secret)
    }
  })
})

