import { readFile } from 'node:fs/promises'
import { join } from 'node:path'
import { homedir, tmpdir } from 'node:os'
import { mkdtemp } from 'node:fs/promises'
import { describe, expect, it, vi } from 'vitest'
import { apply, resolveOutputPath } from '../src/index.ts'
import { verifyReceiptFile } from '../src/receipt.ts'

interface ListenerMap {
  'session/event'?: (session: { id: string }, event: {
    type: string
    seq: number
    time: number
    data: unknown
  }) => void
  'tools/result'?: (exec: {
    name: string
    callId: string
    rootCallId: string
    arguments: unknown
    parent?: symbol
    agent?: { session: { id: string } }
  }, result: { isError: boolean; content: readonly unknown[]; value?: unknown }) => void
}

function contextFixture() {
  const listeners: ListenerMap = {}
  let disposer: (() => Promise<void>) | undefined
  const warn = vi.fn()
  const ctx = {
    on(name: keyof ListenerMap, listener: NonNullable<ListenerMap[keyof ListenerMap]>) {
      Object.assign(listeners, { [name]: listener })
      return () => { delete listeners[name] }
    },
    effect(execute: () => () => Promise<void>) {
      disposer = execute()
    },
    logger: { warn },
  }
  return { ctx, listeners, warn, close: async () => { await disposer?.() } }
}

describe('observe-only plugin', () => {
  it('defaults beneath DSH_HOME and never selects the working directory', () => {
    const safeHome = join(tmpdir(), 'safe-dsh-home')
    const workspace = join(tmpdir(), 'workspace')
    expect(resolveOutputPath(undefined, safeHome, workspace))
      .toBe(join(safeHome, 'evidence-audit', 'evidence-receipts.jsonl'))
    expect(resolveOutputPath(undefined, '   ', workspace))
      .toBe(join(homedir(), '.dsh', 'evidence-audit', 'evidence-receipts.jsonl'))
  })

  it('observes both feeds without mutating their payloads or storing plaintext', async () => {
    const home = await mkdtemp(join(tmpdir(), 'qiushi-home-'))
    const path = join(home, 'receipts.jsonl')
    const fixture = contextFixture()
    await apply(fixture.ctx as never, { outputPath: path })
    const event = Object.freeze({
      type: 'user/message',
      seq: 1,
      time: 100,
      data: Object.freeze({ content: Object.freeze([{ type: 'text', text: 'private-message' }]) }),
    })
    const exec = Object.freeze({
      name: 'bash',
      callId: 'call-private',
      rootCallId: 'call-private',
      arguments: Object.freeze({ command: 'private-command' }),
      agent: Object.freeze({ session: Object.freeze({ id: 'private-session' }) }),
    })
    const result = Object.freeze({
      isError: false,
      value: Object.freeze({ stdout: 'private-result' }),
      content: Object.freeze([{ type: 'text', text: 'private-result' }]),
    })

    fixture.listeners['session/event']?.({ id: 'private-session' }, event)
    fixture.listeners['tools/result']?.(exec, result)
    await fixture.close()

    expect(event.data.content[0]?.text).toBe('private-message')
    expect(exec.arguments.command).toBe('private-command')
    expect(result.value.stdout).toBe('private-result')
    expect(await verifyReceiptFile(path)).toMatchObject({ records: 2 })
    const raw = await readFile(path, 'utf8')
    for (const secret of ['private-message', 'private-command', 'private-result', 'private-session', 'call-private']) {
      expect(raw).not.toContain(secret)
    }
  })

  it('contains unsupported observed values and continues with later receipts', async () => {
    const home = await mkdtemp(join(tmpdir(), 'qiushi-home-'))
    const path = join(home, 'receipts.jsonl')
    const fixture = contextFixture()
    await apply(fixture.ctx as never, { outputPath: path })
    const circular: Record<string, unknown> = {}
    circular.self = circular

    expect(() => fixture.listeners['session/event']?.({ id: 'session-a' }, {
      type: 'invalid/cycle', seq: 0, time: 100, data: circular,
    })).not.toThrow()
    expect(() => fixture.listeners['tools/result']?.({
      name: 'invalid-tool', callId: 'call-a', rootCallId: 'call-a', arguments: 1n,
    }, { isError: false, content: [] })).not.toThrow()
    expect(() => fixture.listeners['session/event']?.({ id: 'session-a' }, {
      type: 'valid/event', seq: 1, time: 101, data: { valid: true },
    })).not.toThrow()
    await fixture.close()

    expect(fixture.warn).toHaveBeenCalledTimes(2)
    await expect(verifyReceiptFile(path)).resolves.toMatchObject({ records: 1 })
  })

  it('records tools/result and session/event observations separately for one logical tool result', async () => {
    const home = await mkdtemp(join(tmpdir(), 'qiushi-home-'))
    const path = join(home, 'receipts.jsonl')
    const fixture = contextFixture()
    await apply(fixture.ctx as never, { outputPath: path })

    fixture.listeners['tools/result']?.({
      name: 'same-tool', callId: 'same-call', rootCallId: 'same-call', arguments: {},
      agent: { session: { id: 'same-session' } },
    }, { isError: false, content: [] })
    fixture.listeners['session/event']?.({ id: 'same-session' }, {
      type: 'tool/result', seq: 4, time: 100, data: { callId: 'same-call' },
    })
    await fixture.close()

    const receipts = (await readFile(path, 'utf8')).trimEnd().split('\n').map(line => JSON.parse(line))
    expect(receipts.map(receipt => receipt.kind)).toEqual(['tool-result', 'session-event'])
    expect(receipts).toHaveLength(2)
  })
})

