import { mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { mkdtemp } from 'node:fs/promises'
import { describe, expect, it } from 'vitest'
import {
  EvidenceReceiptWriter,
  canonicalJson,
  hashObservedValue,
  verifyReceiptFile,
} from '../src/receipt.ts'

const fixedClock = (() => {
  let time = 1_700_000_000_000
  return () => time++
})()

describe('receipt primitives', () => {
  it('canonicalizes object keys recursively and preserves array order', () => {
    expect(canonicalJson({ z: 1, a: { y: 2, x: [3, { b: 4, a: 5 }] } }))
      .toBe('{"a":{"x":[3,{"a":5,"b":4}],"y":2},"z":1}')
  })

  it('hashes the canonical observed value without returning it', () => {
    const first = hashObservedValue({ b: 2, a: 1 })
    const second = hashObservedValue({ a: 1, b: 2 })
    expect(first).toMatch(/^sha256:[0-9a-f]{64}$/)
    expect(first).toBe(second)
    expect(first).not.toContain('"a"')
    expect(first).toBe('sha256:43258cff783fe7036d8a43033f830adfc60ec037382473548ac742b888292777')
  })

  it('rejects non-JSON and non-plain values without silently omitting them', () => {
    expect(() => canonicalJson(undefined)).toThrow(/\$ contains non-JSON undefined/)
    expect(() => canonicalJson({ missing: undefined })).toThrow(/\$\.missing contains non-JSON undefined/)
    expect(() => canonicalJson([undefined])).toThrow(/\$\[0\] contains non-JSON undefined/)
    expect(() => canonicalJson(new Array(1))).toThrow(/\$\[0\] contains a non-JSON array hole/)
    expect(() => canonicalJson(1n)).toThrow(/\$ contains non-JSON bigint/)
    expect(() => canonicalJson(new Date(0))).toThrow(/\$ is not a plain JSON object/)
    expect(() => canonicalJson(new Map([['key', 'value']]))).toThrow(/\$ is not a plain JSON object/)
    expect(() => canonicalJson(new class Box { value = 1 }())).toThrow(/\$ is not a plain JSON object/)
    expect(() => canonicalJson(new Proxy({}, {}))).toThrow(/\$ is not a plain JSON object/)
    expect(() => canonicalJson(new class List extends Array<unknown> {}())).toThrow(/\$ is not a plain JSON array/)
    expect(() => canonicalJson({ [Symbol('key')]: 'value' })).toThrow(/\$ contains a non-JSON symbol key/)
    const withGetter = Object.defineProperty({}, 'value', {
      enumerable: true,
      get: () => { throw new Error('getter must not execute') },
    })
    expect(() => canonicalJson(withGetter)).toThrow(/\$\.value contains a non-JSON accessor/)
    const withHidden = Object.defineProperty({}, 'hidden', { value: true })
    expect(() => canonicalJson(withHidden)).toThrow(/\$\.hidden is a non-JSON non-enumerable property/)
    expect(() => canonicalJson(Object.assign([], { extra: true }))).toThrow(/non-JSON array property "extra"/)
  })

  it('rejects cycles with a bounded path error', () => {
    const circular: Record<string, unknown> = {}
    circular.self = circular
    expect(() => canonicalJson(circular)).toThrow(/\$\.self contains a circular reference/)
  })

  it('sorts keys by UTF-16 code units and hashes UTF-8 without Unicode normalization', () => {
    const nfc = '\u00e9'
    const nfd = 'e\u0301'
    expect(canonicalJson({ '\ud83d\ude00': 4, [nfc]: 3, [nfd]: 2, a: 1 }))
      .toBe(`{"a":1,"${nfd}":2,"${nfc}":3,"\ud83d\ude00":4}`)
    expect(hashObservedValue(nfc)).not.toBe(hashObservedValue(nfd))
  })

  it('appends a deterministic previous-hash chain and verifies it', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-evidence-'))
    const path = join(directory, 'receipts.jsonl')
    const writer = await EvidenceReceiptWriter.open(path, fixedClock)
    const first = writer.append({
      kind: 'session-event',
      sessionIdHash: hashObservedValue('session-a'),
      eventType: 'turn/start',
      eventSeq: 0,
      eventTime: 10,
      eventDataHash: hashObservedValue({ turn: 1 }),
    })
    const second = writer.append({
      kind: 'tool-result',
      sessionIdHash: hashObservedValue('session-a'),
      toolName: 'bash',
      callIdHash: hashObservedValue('call-a'),
      rootCallIdHash: hashObservedValue('call-a'),
      argumentsHash: hashObservedValue({ command: 'secret' }),
      outcomeHash: hashObservedValue({ content: [{ type: 'text', text: 'secret' }] }),
      isError: false,
      hasParent: false,
    })
    await writer.close()

    expect(first.previousRecordHash).toBe(null)
    expect(second.previousRecordHash).toBe(first.recordHash)
    expect(await verifyReceiptFile(path)).toEqual({ records: 2, lastRecordHash: second.recordHash })
    const resumed = await EvidenceReceiptWriter.open(path, fixedClock)
    const third = resumed.append({
      kind: 'session-event',
      sessionIdHash: hashObservedValue('session-a'),
      eventType: 'turn/end',
      eventSeq: 1,
      eventTime: 11,
      eventDataHash: hashObservedValue({ turn: 1 }),
    })
    await resumed.close()
    expect(third.sequence).toBe(2)
    expect(third.previousRecordHash).toBe(second.recordHash)
    expect(await verifyReceiptFile(path)).toEqual({ records: 3, lastRecordHash: third.recordHash })
    const raw = await readFile(path, 'utf8')
    expect(raw).not.toContain('secret')
  })

  it('refuses to resume a malformed chain', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-evidence-'))
    const path = join(directory, 'receipts.jsonl')
    await mkdir(directory, { recursive: true })
    await writeFile(path, '{"schemaVersion":1,"recordHash":"sha256:bad"}\n', 'utf8')
    await expect(EvidenceReceiptWriter.open(path, fixedClock)).rejects.toThrow(/invalid receipt chain/)
  })

  it('detects an unmodified prefix truncation and a partial tail record', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-evidence-'))
    const path = join(directory, 'receipts.jsonl')
    const writer = await EvidenceReceiptWriter.open(path, fixedClock)
    for (const eventSeq of [0, 1, 2]) {
      writer.append({
        kind: 'session-event',
        sessionIdHash: hashObservedValue('session-a'),
        eventType: 'turn/test',
        eventSeq,
        eventTime: eventSeq,
        eventDataHash: hashObservedValue({ eventSeq }),
      })
    }
    await writer.close()
    const original = await readFile(path, 'utf8')
    const lines = original.trimEnd().split('\n')

    await writeFile(path, `${lines.slice(1).join('\n')}\n`, 'utf8')
    await expect(EvidenceReceiptWriter.open(path, fixedClock)).rejects.toThrow(/non-contiguous sequence/)

    await writeFile(path, `${original}{"schemaVersion":1`, 'utf8')
    await expect(EvidenceReceiptWriter.open(path, fixedClock)).rejects.toThrow(/complete JSONL record/)
  })

  it('detects a retained-line edit but cannot detect complete suffix truncation', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-evidence-'))
    const path = join(directory, 'receipts.jsonl')
    const writer = await EvidenceReceiptWriter.open(path, fixedClock)
    for (const eventSeq of [0, 1]) {
      writer.append({
        kind: 'session-event',
        sessionIdHash: hashObservedValue('session-a'),
        eventType: 'turn/test',
        eventSeq,
        eventTime: eventSeq,
        eventDataHash: hashObservedValue({ eventSeq }),
      })
    }
    await writer.close()
    const lines = (await readFile(path, 'utf8')).trimEnd().split('\n')

    await writeFile(path, `${lines.join('\n').replace('turn/test', 'turn/edit')}\n`, 'utf8')
    await expect(verifyReceiptFile(path)).rejects.toThrow(/recordHash does not match/)

    await writeFile(path, `${lines[0]}\n`, 'utf8')
    await expect(verifyReceiptFile(path)).resolves.toMatchObject({ records: 1 })
  })

  it('cannot distinguish whole-file deletion from first use', async () => {
    const directory = await mkdtemp(join(tmpdir(), 'qiushi-evidence-'))
    const path = join(directory, 'receipts.jsonl')
    const writer = await EvidenceReceiptWriter.open(path, fixedClock)
    writer.append({
      kind: 'session-event',
      sessionIdHash: hashObservedValue('session-a'),
      eventType: 'turn/test',
      eventSeq: 0,
      eventTime: 0,
      eventDataHash: hashObservedValue(null),
    })
    await writer.close()
    await rm(path)

    const replacement = await EvidenceReceiptWriter.open(path, fixedClock)
    replacement.append({
      kind: 'session-event',
      sessionIdHash: hashObservedValue('session-b'),
      eventType: 'turn/test',
      eventSeq: 0,
      eventTime: 0,
      eventDataHash: hashObservedValue(null),
    })
    await replacement.close()
    await expect(verifyReceiptFile(path)).resolves.toMatchObject({ records: 1 })
  })
})

