import { readFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { applyEntryPatches, entryListSchema } from '@deepseek-ai/cordis-plugin-include'
import yaml from 'js-yaml'
import { describe, expect, it } from 'vitest'

const upstreamCommit = '47f943859bef60e4160492346772ded9b24f765a'

describe(`DSH bundle composition at ${upstreamCommit}`, () => {
  it('uses the official patch parser and patch application semantics', async () => {
    const manifest = JSON.parse(await readFile(resolve('package.json'), 'utf8')) as {
      name: string
      dsh?: { bundle?: { patch?: string } }
    }
    const patch = manifest.dsh?.bundle?.patch
    expect(patch).toBe('./cordis.patch.yml')
    if (patch === undefined) throw new Error('bundle patch is absent')
    const text = await readFile(resolve(patch), 'utf8')
    const patches = yaml.load(text, { schema: entryListSchema })
    expect(Array.isArray(patches)).toBe(true)
    const warnings: string[] = []
    const entries = applyEntryPatches([], patches as never[], (message, ...args) => {
      warnings.push(`${message} ${args.join(' ')}`)
    })
    expect(warnings).toEqual([])
    expect(entries).toEqual([{
      id: 'qiushi-evidence-audit',
      name: manifest.name,
    }])
  })
})

